const SIDEBAR_KEY='central-v6:sidebar';
function sidebarMode(){return localStorage.getItem(SIDEBAR_KEY)||'expanded'}
function applySidebarCollapse(){
 const app=document.getElementById('appRoot'); if(!app) return;
 const collapsed=sidebarMode()==='collapsed';
 app.classList.toggle('sidebar-collapsed',collapsed);
 app.classList.toggle('sidebar-expanded-manual',!collapsed);
 const t=document.getElementById('sidebarToggle');
 if(t) t.setAttribute('aria-pressed', collapsed ? 'true' : 'false');
}
function toggleSidebarCollapse(){
 localStorage.setItem(SIDEBAR_KEY, sidebarMode()==='collapsed' ? 'expanded' : 'collapsed');
 applySidebarCollapse();
}
function closeMobileSidebar(){
 const aside=document.getElementById('centralSidebar'),back=document.getElementById('mobileSidebarBackdrop'),btn=document.getElementById('mobileMenuBtn');
 aside?.classList.remove('mobile-open');back?.classList.remove('show');back?.setAttribute('aria-hidden','true');btn?.setAttribute('aria-expanded','false');
}
function toggleMobileSidebar(){
 const aside=document.getElementById('centralSidebar'),back=document.getElementById('mobileSidebarBackdrop'),btn=document.getElementById('mobileMenuBtn');
 if(!aside)return;
 const open=!aside.classList.contains('mobile-open');
 aside.classList.toggle('mobile-open',open);back?.classList.toggle('show',open);back?.setAttribute('aria-hidden',open?'false':'true');btn?.setAttribute('aria-expanded',open?'true':'false');
}
window.addEventListener('resize',()=>{if(window.innerWidth>680)closeMobileSidebar()});

const CENTRAL_THEME_KEY='central-v6:appearance';
function centralThemeMode(){return localStorage.getItem(CENTRAL_THEME_KEY)||'oled'}
function resolvedCentralTheme(mode=centralThemeMode()){
 if(mode==='oled')return 'dark';
 if(mode==='system'){const sys=window.matchMedia&&window.matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';return sys==='light'?'light':'dark'}
 if(mode==='light')return 'light';
 return 'dark';
}
function refreshCentralThemeButtons(){
 const mode=centralThemeMode();
 document.querySelectorAll('[data-central-theme-choice]').forEach(b=>b.classList.toggle('active',b.dataset.centralThemeChoice===mode));
 document.documentElement.dataset.centralTheme=resolvedCentralTheme();
}
function setCentralTheme(mode){
 if(!['light','dark','oled','system'].includes(mode))return;
 localStorage.setItem(CENTRAL_THEME_KEY,mode);applyCentralTheme();
}
function openCentralSettings(){
 const el=document.getElementById('centralSettingsBackdrop');if(!el)return;
 el.classList.remove('hidden');refreshCentralThemeButtons();
}
function closeCentralSettings(){document.getElementById('centralSettingsBackdrop')?.classList.add('hidden')}
function decorandoThemeBridge(theme){
 const f=document.getElementById('leiSecaFrame');if(!f?.contentWindow)return;
 try{
   if(typeof f.contentWindow.setPref==='function')f.contentWindow.setPref('theme',theme);
   else if(f.contentDocument?.documentElement)f.contentDocument.documentElement.dataset.theme=theme;
 }catch(e){}
}
function vadeThemeBridge(theme){
 const f=document.getElementById('vadeMecumFrame'),doc=f?.contentDocument;if(!doc)return;
 try{
   let style=doc.getElementById('central-theme-bridge');
   if(!style){style=doc.createElement('style');style.id='central-theme-bridge';doc.head.appendChild(style)}
   if(theme==='dark'){
     style.textContent=`
       :root{--bg:#09111f!important;--panel:#0d1727!important;--ink:#f1f5fb!important;--muted:#92a6c2!important;--line:#26364f!important;--soft:#111d2f!important}
       html,body,#app,.vm-shell,.vm-main{background:#09111f!important;color:#f1f5fb!important}
       .vm-header,.vm-sidebar,.vm-toolbar,.vm-intro,.vm-article,.vm-index,.vm-law-head-actions button,.vm-law-head-actions a,
       .vm-search input,.vm-filter,.vm-mobile-laws select,.vm-comment,.vm-comment-form textarea{background:#0d1727!important;color:#f1f5fb!important;border-color:#26364f!important}
       .vm-article-top,.vm-marker,.vm-comments{background:#111d2f!important;border-color:#26364f!important}
       .vm-law-btn{color:#dce5f1!important}.vm-law-btn:hover,.vm-law-btn.active{background:#17243a!important;border-color:#334760!important}
       .vm-law-code{background:#17243a!important;color:#b7c8de!important}.vm-law-btn.active .vm-law-code{background:#6755e7!important;color:#fff!important}
       .vm-filter.active{background:#6755e7!important;border-color:#6755e7!important;color:#fff!important}
       .vm-law-head h1,.vm-article-title h2,.vm-brand strong{color:#f1f5fb!important}
       .vm-law-head p,.vm-results-info,.vm-article-title small,.vm-sidebar-foot,.vm-brand small{color:#92a6c2!important}
       .vm-index-backdrop{background:rgba(2,7,16,.72)!important}
     `;
   }else{
     style.textContent=`
       :root{--bg:#f4f6f9!important;--panel:#fff!important;--ink:#182235!important;--muted:#68778e!important;--line:#dce3ec!important;--soft:#f7f9fc!important}
       html,body,#app,.vm-shell,.vm-main{background:#f4f6f9!important;color:#182235!important}
       .vm-filter.active{background:#6755e7!important;border-color:#6755e7!important;color:#fff!important}
       .vm-law-btn.active .vm-law-code{background:#6755e7!important;color:#fff!important}
     `;
   }
 }catch(e){}
}
function applyCentralTheme(){
 const theme=resolvedCentralTheme();
 document.documentElement.dataset.centralTheme=theme;
 document.documentElement.style.colorScheme=theme;
 refreshCentralThemeButtons();
 decorandoThemeBridge(theme);vadeThemeBridge(theme);
}
if(window.matchMedia){
 const mq=window.matchMedia('(prefers-color-scheme: dark)');
 const cb=()=>{if(centralThemeMode()==='system')applyCentralTheme()};
 if(mq.addEventListener)mq.addEventListener('change',cb);else if(mq.addListener)mq.addListener(cb);
}

function hideViews(){['homeView','disciplinesView','agendaView','performanceView','tecCadernosView','ankiView','leiSecaView','vadeMecumView','moduleView'].forEach(id=>$(id).classList.add('hidden'))}
function setNav(btn){document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');closeMobileSidebar()}
function centralShowNativeView(viewId,label,btn){
 try{
  ['homeView','disciplinesView','agendaView','performanceView','tecCadernosView','ankiView','leiSecaView','vadeMecumView','moduleView'].forEach(id=>{
   const el=$(id);if(el)el.classList.add('hidden');
  });
  const view=$(viewId);if(!view)throw new Error('Tela não encontrada: '+viewId);
  view.classList.remove('hidden');
  try{view.classList.add('central-view-visible')}catch(_){}
  if($('crumb'))$('crumb').textContent=label||'';
  try{setNav(btn)}catch(_){try{closeMobileSidebar()}catch(__){}}
  try{view.scrollTop=0}catch(_){}
  try{window.scrollTo(0,0)}catch(_){}
  return view;
 }catch(e){console.error('Falha ao exibir tela interna',viewId,e);return null}
}
function centralNativeError(hostId,message){
 const host=$(hostId);if(!host)return;
 host.innerHTML='<div class="card" style="padding:18px;border-color:#7f1d1d"><b>Não foi possível carregar este conteúdo.</b><div class="muted small" style="margin-top:7px">'+esc(message||'Erro de carregamento')+'</div></div>';
}
function centralSidebarAction(action,btn){
 try{
  if(action==='agenda'){openAgenda(btn);return false}
  if(action==='disciplines'){openDisciplines(btn);return false}
  const routes={
   home:()=>openHome(btn),anki:()=>openEmbeddedTool('anki',{},btn),decorando:()=>openEmbeddedTool('decorando',{},btn),
   vade:()=>openEmbeddedTool('vade',{},btn),performance:()=>openPerformance(btn),'tec-cadernos':()=>openTecCadernos(btn),settings:()=>openCentralSettings()
  };
  const run=routes[action];if(!run)throw new Error('Destino lateral inválido: '+action);run();
 }catch(e){
  console.error('Falha na navegação lateral',action,e);
  // Não volta automaticamente para o Início: isso mascarava erros e fazia Agenda/Disciplinas parecerem não abrir.
  if(action==='agenda'){centralShowNativeView('agendaView','Agenda',btn);centralNativeError('agendaEditor',e?.message||e)}
  else if(action==='disciplines'){centralShowNativeView('disciplinesView','Disciplinas',btn);centralNativeError('disciplineGrid',e?.message||e)}
 }
 return false;
}
function openHome(btn){
 const view=centralShowNativeView('homeView','Início',btn||document.querySelector('.nav button'));
 if(!view)return false;
 try{renderAll()}catch(e){console.warn('Renderização parcial do Início',e)}
 return false;
}
function openDisciplines(btn){
 const view=centralShowNativeView('disciplinesView','Disciplinas',btn);
 if(!view)return false;
 // A tela aparece primeiro. A leitura de progresso não pode impedir a navegação.
 setTimeout(()=>{try{renderDisciplineGrid()}catch(e){console.error('Falha ao montar Disciplinas',e);centralNativeError('disciplineGrid',e?.message||e)}},0);
 return false;
}
function openAgenda(btn){
 const view=centralShowNativeView('agendaView','Agenda',btn);
 if(!view)return false;
 // A tela aparece primeiro. Dados corrompidos/indisponíveis não fecham mais a Agenda.
 setTimeout(()=>{try{renderAgendaEditor()}catch(e){console.error('Falha ao montar Agenda',e);centralNativeError('agendaEditor',e?.message||e)}},0);
 return false;
}
function openPerformance(btn){
 const view=centralShowNativeView('performanceView','Desempenho',btn);if(!view)return false;
 try{renderPerformance()}catch(e){console.warn('Falha ao montar Desempenho',e)}return false;
}
const queueOpenAnkiIntegrated=function(btn=null,deck=null){
 const requested={btn,deck};
 setTimeout(()=>{
  const ready=window.openAnkiIntegrated;
  if(typeof ready==='function'&&ready!==queueOpenAnkiIntegrated)ready(requested.btn,requested.deck);
  else alert('O Anki incorporado não terminou de carregar. Aguarde um instante e toque novamente.');
 },0);
};
if(typeof window.openAnkiIntegrated!=='function')window.openAnkiIntegrated=queueOpenAnkiIntegrated;
const RLM_DISCIPLINA_B64='';

let rlmDisciplinaLoaded=false;
let rlmPdfObjectUrl=null;

function decodeEmbeddedUtf8(b64){
 const bin=atob(b64),bytes=new Uint8Array(bin.length);
 for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
 return new TextDecoder().decode(bytes);
}
function decodeEmbeddedBytes(b64){
 const bin=atob(b64),bytes=new Uint8Array(bin.length);
 for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
 return bytes;
}
let rlmPdfSourceLoading=null;
function loadRlmPdfSource(){
 if(typeof RLM_SOURCE_PDF_B64!=='undefined')return Promise.resolve(true);
 if(rlmPdfSourceLoading)return rlmPdfSourceLoading;
 const files=['000-init','001','002','003','004','005','006','007','008','009','010','011','012','013','014-final'];
 rlmPdfSourceLoading=files.reduce((p,n)=>p.then(()=>new Promise((resolve,reject)=>{
   const s=document.createElement('script');
   s.src='/central-structural-v66119/rlm-source-pdf-b64-'+n+'.js?v=66119s2';
   s.async=false;s.onload=resolve;s.onerror=()=>reject(new Error('Falha ao carregar PDF RLM'));
   document.head.appendChild(s);
 })),Promise.resolve()).then(()=>true).catch(e=>{rlmPdfSourceLoading=null;throw e});
 return rlmPdfSourceLoading;
}
async function openRlmPdf(page=1){
 const p=Math.max(1,parseInt(page,10)||1);
 try{
  await loadRlmPdfSource();
  if(!rlmPdfObjectUrl)rlmPdfObjectUrl=URL.createObjectURL(new Blob([decodeEmbeddedBytes(RLM_SOURCE_PDF_B64)],{type:'application/pdf'}));
  window.open(rlmPdfObjectUrl+'#page='+p,'_blank');
 }catch(e){console.error('[RLM PDF lazy]',e);alert('Não foi possível abrir o PDF-fonte neste navegador. As figuras necessárias já estão incorporadas às questões.')}
}
function buildEmbeddedRlmDoc(target){
 const safe=/^(?:calculo|rlm[1-9])$/.test(String(target||''))?String(target):'';
 const doc=decodeEmbeddedUtf8(RLM_DISCIPLINA_B64);
 return doc.replace('</head>','<script>window.__RLM_INITIAL_TARGET='+JSON.stringify(safe)+';<\/script></head>');
}
function activateEmbeddedRlm(frame,target){
 try{
  const w=frame?.contentWindow;if(!w)return false;
  if(target==='calculo'){if(typeof w.openFastHome!=='function')return false;w.openFastHome();}
  else if(/^rlm[1-9]$/.test(target)){if(typeof w.openModule!=='function')return false;w.openModule(target);}
  else{if(typeof w.showHome!=='function')return false;w.showHome();}
  try{w.scrollTo(0,0)}catch(_){}return true;
 }catch(e){console.error('Falha ao abrir a seção incorporada de RLM',e);return false}
}
function ensureEmbeddedRlmReady(frame,target,attempt=0){
 if(!frame)return;if(activateEmbeddedRlm(frame,target)){rlmDisciplinaLoaded=true;return}
 if(attempt<12)setTimeout(()=>ensureEmbeddedRlmReady(frame,target,attempt+1),40+attempt*20);
}
function internalRouteParam(value,key){
 try{
  const query=String(value).split('?')[1]?.split('#')[0]||'';
  return new URLSearchParams(query).get(key)||'';
 }catch(e){return ''}
}
function routeIntegratedCentralModule(value,title,btn){
 if(/^(?:\.\/)?anki\.html(?:[?#]|$)/.test(value)){
  openEmbeddedTool('anki',{deck:internalRouteParam(value,'deck')||null,title:title||'Anki'},btn);return true;
 }
 if(/^(?:\.\/)?decorando_lei_seca\.html(?:[?#]|$)/.test(value)){
  openEmbeddedTool('decorando',{discipline:internalRouteParam(value,'discipline')||null,topicId:internalRouteParam(value,'topic')||null},btn);return true;
 }
 if(/^(?:\.\/)?vade_mecum\.html(?:[?#]|$)/.test(value)){
  openEmbeddedTool('vade',{lawId:internalRouteParam(value,'law')||null},btn);return true;
 }
 if(/^(?:\.\/)?rlm_disciplina\.html(?:[?#]|$)/.test(value)){
  const target=(String(value).split('#')[1]||'').split('&')[0];
  openEmbeddedTool('rlm',{target},btn);return true;
 }
 if(/^(?:\.\/)?decorando_civil_analista\.html(?:[?#]|$)/.test(value)){
  openLeiSecaEnxuta(btn,'civil');return true;
 }
 if(/^(?:\.\/)?modules\/anki\/index\.html(?:[?#]|$)/.test(value)){
  openAnkiDeck(internalRouteParam(value,'deck'),title);return true;
 }
 if(/^(?:\.\/)?modules\/lei-seca-juridica\/index\.html(?:[?#]|$)/.test(value)){
  openVadeMecum(btn);return true;
 }
 const cf=value.match(/^(?:\.\/)?modules\/cf\/index\.html\?[^#]*\bweek=(w\d+)/);
 if(cf){openCfLast(cf[1]);return true}
 if(/^(?:\.\/)?modules\/portugues\/index\.html(?:[?#]|$)/.test(value)){
  const page=internalRouteParam(value,'page');
  if(page==='week1')openPtLast(1,1);else jumpSubject('pt');
  return true;
 }
 return false;
}
function openInternal(url,title,btn){
 const value=String(url||'');
 if(routeIntegratedCentralModule(value,title,btn))return;
 hideViews();$('moduleView').classList.remove('hidden');try{$('moduleView').classList.add('central-view-visible')}catch(_){}$('crumb').textContent=title;setNav(btn);
 const f=$('moduleFrame'),isRlm=/^(?:\.\/)?rlm_disciplina\.html(?:[?#]|$)/.test(value);
 if(isRlm){
  const target=(String(value).split('#')[1]||'').split('&')[0];
  openEmbeddedTool('rlm',{target},btn);
  return;
 }else{
  rlmDisciplinaLoaded=false;delete f.dataset.embeddedModule;f.removeAttribute('srcdoc');f.src=value;
 try{moduleFrameWatch(value)}catch(_){}
 }
 saveLast({url:value,title,at:Date.now()});
}

const VADE_MECUM_B64='';
