function resetEmbeddedPageTop(frame){
 try{
  if(!frame)return;
  frame.scrollTop=0;frame.scrollLeft=0;
  const w=frame.contentWindow,d=frame.contentDocument||w?.document;
  if(w)w.scrollTo(0,0);
  if(d){
   if(d.scrollingElement){d.scrollingElement.scrollTop=0;d.scrollingElement.scrollLeft=0}
   if(d.documentElement){d.documentElement.scrollTop=0;d.documentElement.scrollLeft=0}
   if(d.body){d.body.scrollTop=0;d.body.scrollLeft=0}
   d.querySelectorAll('.workspace,.filter-list,.law-nav').forEach(el=>{if(el&&el.scrollTop>0)el.scrollTop=0});
  }
 }catch(e){}
}
function activateEmbeddedDecorando(frame,discipline=null){
 try{
  const w=frame.contentWindow;
  if(discipline&&typeof w?.chooseDiscipline==='function')w.chooseDiscipline(discipline);
 }catch(e){console.error('Falha ao selecionar a disciplina no Decorando',e)}
 resetEmbeddedPageTop(frame);
 requestAnimationFrame(()=>resetEmbeddedPageTop(frame));
 setTimeout(()=>resetEmbeddedPageTop(frame),60);
 decorandoThemeBridge(resolvedCentralTheme());
}
