 if(q.real===false)return '';
 const x=((q.q||'')+' '+(q.o||[]).join(' ')).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 if(q.moduleId==='pen-m07'&&(y||0)<2026&&/(violencia domestica|mulher|maria da penha)/.test(x)&&/(decad|representa|queixa|seis meses|6 meses)/.test(x))return 'Lei 15.438/2026: prazo decadencial especial de 12 meses na violência doméstica e familiar contra a mulher.';
