 if(q.moduleId==='pen-m09'&&(y||0)<2026&&/(furto|roubo|estelionato|receptacao|fraude eletronica|repouso noturno|conta laranja|pena)/.test(x))return 'Lei 15.397/2026 alterou penas e figuras patrimoniais. O gabarito exibido é o histórico da prova.';
