 const q=penalSession.list[penalSession.index],ok=i===q.a,st=penalState(),prev=st.answers?.[q.id]||{attempts:0,everWrong:false,lastCorrect:false};
 prev.attempts++;prev.lastCorrect=ok;prev.everWrong=prev.everWrong||!ok;prev.lastAt=Date.now();st.answers=st.answers||{};st.answers[q.id]=prev;penalSave(st);
